import { ok, fail } from './result.js';
import { getCustomer, TIER_DISCOUNTS, normalizeId } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';
import { roundCents } from './money.js';
import { isValidDate } from './dates.js';

/**
 * Validate a discount percent value.
 * @param {unknown} discountPercent
 * @returns {{ ok: boolean }}
 */
function isValidDiscountPercent(discountPercent) {
  return (
    typeof discountPercent === 'number' &&
    !Number.isNaN(discountPercent) &&
    discountPercent >= 0 &&
    discountPercent <= 100
  );
}

/**
 * Create a draft invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number }> }} opts
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines }) {
  // Normalize customer ID
  const normalizedCustomerId = normalizeId(customerId);

  // Validate customer
  const customerResult = getCustomer(normalizedCustomerId);
  if (!customerResult.ok) return customerResult;

  // Validate date format YYYY-MM-DD
  if (!isValidDate(issueDate)) return fail('DATE_INVALID');

  // Validate lines is not empty
  if (!Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');

  // Process lines
  const customer = customerResult.value;
  const tierDiscount = TIER_DISCOUNTS[customer.tier];
  const invoiceLines = [];

  for (const line of lines) {
    // Validate qty
    if (!Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');

    // Validate discount if provided
    if (line.discountPercent !== undefined && !isValidDiscountPercent(line.discountPercent)) {
      return fail('DISCOUNT_INVALID');
    }

    // Get product
    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    const newLine = {
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    };

    // Apply discount: explicit line discount wins, otherwise use tier discount
    const discountPercent = line.discountPercent !== undefined ? line.discountPercent : tierDiscount;
    if (discountPercent > 0) {
      newLine.discountPercent = discountPercent;
    }

    invoiceLines.push(newLine);
  }

  return ok({
    customerId: normalizedCustomerId,
    issueDate,
    status: 'draft',
    lines: invoiceLines,
  });
}

/**
 * Calculate the total for a single line (quantity times unit price).
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number}
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate the discount for a single line.
 * @param {{ qty: number, unitPrice: number, discountPercent?: number }} line
 * @returns {number}
 */
export function lineDiscount(line) {
  if (!line.discountPercent) return 0;
  const total = lineTotal(line);
  const discount = roundCents((total * line.discountPercent) / 100);
  return Math.max(0, discount);
}

/**
 * Calculate VAT for a single line (on the amount after discount).
 * @param {{ qty: number, unitPrice: number, vatRate: number, discountPercent?: number }} line
 * @returns {number}
 */
export function lineVat(line) {
  const total = lineTotal(line);
  const discount = lineDiscount(line);
  const amountAfterDiscount = Math.max(0, total - discount);
  const vat = roundCents((amountAfterDiscount * line.vatRate) / 100);
  return Math.max(0, vat);
}

/**
 * Calculate subtotal, discount, VAT, and total for an invoice.
 * @param {{ lines: Array }} invoice
 * @returns {{ subtotal: number, discount: number, vat: number, total: number }}
 */
export function invoiceTotals(invoice) {
  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
  const discount = invoice.lines.reduce((sum, line) => sum + lineDiscount(line), 0);
  const vat = invoice.lines.reduce((sum, line) => sum + lineVat(line), 0);
  const total = Math.max(0, subtotal - discount + vat);
  return { subtotal, discount, vat, total };
}

/**
 * Add a line to a draft invoice. If the SKU already exists, increase its quantity.
 * @param {{ status: string, lines: Array, customerId: string, issueDate: string }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} opts
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  // Check if invoice is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Validate qty
  if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');

  // Validate discount if provided
  if (discountPercent !== undefined && !isValidDiscountPercent(discountPercent)) {
    return fail('DISCOUNT_INVALID');
  }

  // Get product
  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  // Get customer for tier discount
  const customerResult = getCustomer(invoice.customerId);
  if (!customerResult.ok) return customerResult;

  const product = productResult.value;
  const tierDiscount = TIER_DISCOUNTS[customerResult.value.tier];
  const newLines = invoice.lines.map((line) => ({ ...line }));

  // Check if SKU already exists
  const existingLineIndex = newLines.findIndex((line) => line.sku === sku);
  if (existingLineIndex >= 0) {
    // Increase quantity
    const updated = {
      ...newLines[existingLineIndex],
      qty: newLines[existingLineIndex].qty + qty,
    };
    // Update discount if provided, otherwise keep existing or apply tier discount
    if (discountPercent !== undefined) {
      if (discountPercent > 0) {
        updated.discountPercent = discountPercent;
      } else {
        delete updated.discountPercent;
      }
    } else if (!updated.discountPercent && tierDiscount > 0) {
      // Apply tier discount if line doesn't have one
      updated.discountPercent = tierDiscount;
    }
    newLines[existingLineIndex] = updated;
  } else {
    // Add new line
    const newLine = {
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    };
    const effectiveDiscount = discountPercent !== undefined ? discountPercent : tierDiscount;
    if (effectiveDiscount > 0) {
      newLine.discountPercent = effectiveDiscount;
    }
    newLines.push(newLine);
  }

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: invoice.status,
    lines: newLines,
  });
}

/**
 * Remove a line from a draft invoice.
 * @param {{ status: string, lines: Array, customerId: string, issueDate: string }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  // Check if invoice is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Check if line exists
  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex < 0) return fail('LINE_NOT_FOUND');

  // Check if it's the last line
  if (invoice.lines.length === 1) return fail('NO_LINES');

  // Remove the line
  const newLines = invoice.lines.filter((line) => line.sku !== sku);

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: invoice.status,
    lines: newLines,
  });
}

/**
 * Issue a draft invoice, assigning it a number and setting status to 'issued'.
 * @param {{ status: string, customerId: string, issueDate: string, lines: Array }} invoice
 * @param {string[]} existingNumbers
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  // Check if invoice is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Get the next invoice number
  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  return ok({
    number,
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: 'issued',
    lines: invoice.lines.map((line) => ({ ...line })),
  });
}

